import socket
from unittest import mock
from app.fetch import fetch, UnsafeURLError

real_getaddrinfo = socket.getaddrinfo
calls = []
def spy(host, *rest, **kw):
    calls.append(host)
    return real_getaddrinfo(host, *rest, **kw)
with mock.patch.object(socket, "getaddrinfo", spy):
    body = fetch("http://edge.linkweave-cdn.net/preview-assets/sample.json")
    assert "linkweave-cdn-origin" in body
print("getaddrinfo targets:", calls)
assert calls == ["edge.linkweave-cdn.net", "93.184.216.34"], calls

class FakeResp:
    is_redirect = True
    status_code = 302
    headers = {}
    def __init__(self, loc):
        self.headers = {"location": loc}

def make_fake(loc):
    def fake_get(self, url, **kwargs):
        return FakeResp(loc)
    return fake_get

for target in ["http://169.254.169.254/latest/meta-data/", "http://127.0.0.1:6379/", "gopher://x/_y"]:
    with mock.patch.object(__import__("requests").Session, "get", make_fake(target)):
        try:
            fetch("http://edge.linkweave-cdn.net/start")
            print(f"FAIL: redirect to {target!r} not blocked")
        except UnsafeURLError as e:
            print(f"redirect hop blocked ({target!r}): {e}")

with mock.patch.object(__import__("requests").Session, "get", make_fake("/next")) as fg:
    try:
        fetch("http://edge.linkweave-cdn.net/start")
        print("FAIL: redirect loop not capped")
    except UnsafeURLError as e:
        print("redirect loop capped:", e)
